+
+const sourceOutput = sourceSchema.extend({ reason: z.enum([...REASONS, 'STALE']), freshness: z.enum(['CURRENT', 'STALE']) }).strict();
+const hash = z.string().regex(/^[0-9a-f]{64}$/);
